contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(address(this));
        require(beforeTotal <= type(uint256).max - amount, "overflow");
        require(beforeBal <= type(uint256).max - amount, "overflow bal");
        bool reverted;
        try c.stake(amount) { reverted = false; } catch { reverted = true; }
        if (!reverted) {
            assert(c.totalSupply() == beforeTotal + amount && c.balanceOf(address(this)) == beforeBal + amount);
        } else {
            assert(c.totalSupply() == beforeTotal && c.balanceOf(address(this)) == beforeBal);
        }
    }

    receive() external payable {}
}

