contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 stakeAmount, uint256 withdrawAmount) public {
        require(withdrawAmount > 0);
        require(stakeAmount >= withdrawAmount);

        // Add a reward token so reward bookkeeping is exercised during state changes.
        c.addReward(rewardToken);
        rewardToken.call(abi.encodeWithSignature("approve(address,uint256)", address(c), type(uint256).max));

        // Provide the staking tokens needed to stake on behalf of the test contract.
        c.stakingToken().transferFrom(msg.sender, address(this), stakeAmount);
        c.stakingToken().approve(address(c), stakeAmount);

        c.stakeFor(address(this), stakeAmount);

        uint256 totalBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 earnedBefore = c.earned(address(this), rewardToken);

        c.withdraw(withdrawAmount, false);

        uint256 totalAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 earnedAfter = c.earned(address(this), rewardToken);

        assert(
            totalAfter == totalBefore - withdrawAmount &&
            balanceAfter == balanceBefore - withdrawAmount &&
            earnedAfter == earnedBefore
        );
    }

    receive() external payable {}
}

