contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address staker,
        uint256 stakeAmount,
        uint256 withdrawAmount,
        bool claim
    ) public payable {
        require(staker != address(0), "zero staker");
        require(staker != address(c), "staker is contract");
        require(stakeAmount > 0, "zero stake");

        // Fund this test contract so it can provide the staking tokens.
        // The staking token is only accessible through c.stakingToken(), so use a low-level call
        // to its transfer function to send tokens to c's user (this test contract).
        IERC20 stakingToken = c.stakingToken();
        (bool funded, ) = address(stakingToken).call(
            abi.encodeWithSelector(IERC20.transfer.selector, address(this), stakeAmount)
        );
        require(funded, "funding failed");

        // Approve c to pull the stake amount from this test contract.
        (bool approved, ) = address(stakingToken).call(
            abi.encodeWithSelector(IERC20.approve.selector, address(c), stakeAmount)
        );
        require(approved, "approval failed");

        // The test contract is the staker for c.
        uint256 totalBefore = c.totalSupply();
        bool stakeSucceeded;
        try c.stakeFor(address(this), stakeAmount) {
            stakeSucceeded = true;
        } catch {
            stakeSucceeded = false;
        }
        require(stakeSucceeded, "stake failed");

        uint256 totalAfterStake = c.totalSupply();
        uint256 balAfterStake = c.balanceOf(address(this));

        // Attempt withdrawal.  withdraw() takes (uint256 amount, bool claim) and is called by msg.sender.
        bool withdrawSucceeded;
        try c.withdraw(withdrawAmount, claim) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        uint256 totalAfterWithdraw = c.totalSupply();
        uint256 balAfterWithdraw = c.balanceOf(address(this));

        // The general rule: totalSupply and this staker's balance move together.
        // If the call succeeded, the staker's balance decreased by exactly withdrawAmount;
        // if it reverted, the staker's balance and totalSupply are unchanged.
        assert(
            (withdrawSucceeded && balAfterWithdraw + withdrawAmount == balAfterStake && totalAfterWithdraw + withdrawAmount == totalAfterStake) ||
            (!withdrawSucceeded && balAfterWithdraw == balAfterStake && totalAfterWithdraw == totalAfterStake)
        );
    }
}

