contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");

        // Read state before the deciding call (no reward tokens registered in the fresh C).
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeSenderBalance = c.balanceOf(address(this));

        // Perform the staking call; since no reward tokens exist, updateReward is a no-op
        // and there is no external token transfer requirement (requires a staking token
        // whose transferFrom succeeds — in a property test the mock token allows this).
        bool reverted;
        try c.stake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after the call.
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterSenderBalance = c.balanceOf(address(this));

        // General rule: if stake succeeds, totalSupply and the staker's balance
        // increase by exactly the staked amount. Since there are no reward tokens,
        // neither can decrease, and the operation must be additive.
        assert(
            reverted ||
            (afterTotalSupply == beforeTotalSupply + amount &&
             afterSenderBalance == beforeSenderBalance + amount)
        );
    }

    receive() external payable {}
}

