    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0, "amount must be positive");

        IERC20 stakingToken = c.stakingToken();

        uint256 beforeContractStake = stakingToken.balanceOf(address(c));
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeUserStake = c.balanceOf(address(this));

        stakingToken.approve(address(c), amount);
        c.stake(amount);

        uint256 afterStakeContract = stakingToken.balanceOf(address(c));
        uint256 afterStakeTotal = c.totalSupply();
        uint256 afterStakeUser = c.balanceOf(address(this));

        c.withdraw(amount, false);

        uint256 afterWithdrawContract = stakingToken.balanceOf(address(c));
        uint256 afterWithdrawTotal = c.totalSupply();
        uint256 afterWithdrawUser = c.balanceOf(address(this));

        assert(
            afterStakeContract == beforeContractStake + amount &&
            afterStakeTotal == beforeTotalSupply + amount &&
            afterStakeUser == beforeUserStake + amount &&
            afterWithdrawContract == beforeContractStake &&
            afterWithdrawTotal == beforeTotalSupply &&
            afterWithdrawUser == beforeUserStake
        );
    }

    receive() external payable {}
}

