contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, address newMigrator, uint256 amount) public {
        require(amount > 0, "amount must be positive");

        uint256 beforeBal = c.balanceOf(staker);
        uint256 beforeSupply = c.totalSupply();
        require(beforeBal >= amount, "Not enough staked tokens");

        c.setMigrator(newMigrator);

        c.migrateWithdraw(staker, amount);

        uint256 afterBal = c.balanceOf(staker);
        uint256 afterSupply = c.totalSupply();

        assert(afterBal == beforeBal - amount && afterSupply == beforeSupply - amount);
    }

    receive() external payable {}
}

