contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        require(amount > 0);
        require(amount <= c.stakingToken().balanceOf(address(this)));

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(recipient);

        bool reverted;
        try c.stakeFor(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(recipient);

        assert(!reverted && afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount);
    }
}

