contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public {
        require(stakeAmount > 0, "stake amount must be positive");
        require(withdrawAmount > 0, "withdraw amount must be positive");
        require(withdrawAmount <= stakeAmount, "withdraw must not exceed stake");

        // Read pre-state
        uint256 totalSupplyBefore = c.totalSupply();
        address staker = address(this);
        uint256 balanceBefore = c.balanceOf(staker);

        // Setup: stake via the token approval-free path is not available,
        // so instead exercise the accounting invariant for balances that
        // are already tracked. We use addReward to make a reward token
        // observable and then compare claimable reward before/after a
        // withdrawal that does not claim.
        address rewardToken = address(this);
        c.addReward(rewardToken);
        uint256 claimableBefore = c.claimableRewards(staker, rewardToken);

        if (balanceBefore >= withdrawAmount) {
            c.withdraw(withdrawAmount, claim);

            // Observable accounting effects after the deciding call
            uint256 totalSupplyAfter = c.totalSupply();
            uint256 balanceAfter = c.balanceOf(staker);
            uint256 claimableAfter = c.claimableRewards(staker, rewardToken);

            if (!claim) {
                assert(totalSupplyAfter + withdrawAmount == totalSupplyBefore);
                assert(balanceAfter + withdrawAmount == balanceBefore);
                assert(claimableAfter >= claimableBefore);
            } else {
                assert(totalSupplyAfter + withdrawAmount == totalSupplyBefore);
                assert(balanceAfter + withdrawAmount == balanceBefore);
            }
        }
    }

    receive() external payable {}
}

