contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        // Preconditions on parameters only
        require(stakeAmount > 0);
        require(withdrawAmount > 0);
        require(withdrawAmount <= stakeAmount);

        // Setup: this contract must own staking tokens and approve c to move them.
        // The staking token is a public state variable; call its public surface
        // to approve the staking contract.
        IERC20 token = c.stakingToken();
        // Ensure this test contract has enough tokens by checking its balance
        // via the public balanceOf of the token; if not enough, the transferFrom
        // would revert anyway, so we require here only to keep assertions meaningful.
        require(token.balanceOf(address(this)) >= stakeAmount);
        // Approve c to transfer staking tokens (top-level call, not nested).
        bool approved = token.approve(address(c), stakeAmount);
        require(approved);

        // Record before-values observable through c's public surface.
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        // Make the deciding call: stake then withdraw without claiming rewards.
        // Each state-changing call on c must be its own top-level statement.
        c.stake(stakeAmount);

        // After staking, balance should have increased by stakeAmount.
        uint256 balAfterStake = c.balanceOf(address(this));

        // Capture reward accounting before withdrawal to ensure claimableRewards
        // is not affected by a withdrawal with claim=false. We read claimableRewards
        // for every reward token; if there are none, the loop is empty.
        // Read rewardTokens via the public array getter.
        uint256 rewardTokenCount = 0;
        // rewardTokens is a public array; its length is not directly exposed,
        // but we can call the getter and check until it reverts? Cannot loop safely
        // without length. Instead, since we cannot know the number of reward tokens
        // from outside, we focus the rule on totalSupply and balanceOf, which are
        // always observable.

        uint256 totalAfterStake = c.totalSupply();

        // Record claimable rewards for address(this) for a dummy token (address(0))
        // and for the staking token if it is also a reward token; but to keep the
        // rule simple and strong, we assert only on totalSupply and balanceOf.
        uint256 claimableBefore = c.claimableRewards(address(this), address(token));

        // Withdraw without claiming rewards.
        c.withdraw(withdrawAmount, false);

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 claimableAfter = c.claimableRewards(address(this), address(token));

        // General rule: with claim=false, withdrawing `withdrawAmount` reduces
        // totalSupply and the caller's staked balance by exactly `withdrawAmount`,
        // and does not change claimableRewards for any token (checked here for
        // the staking token, which is the only token whose claimable balance we
        // can address without knowing all reward tokens; the rule holds for all
        // tokens in principle).
        assert(
            totalAfterStake == totalBefore + stakeAmount &&
            balAfterStake == balBefore + stakeAmount &&
            totalAfter == totalAfterStake - withdrawAmount &&
            balAfter == balAfterStake - withdrawAmount &&
            claimableAfter == claimableBefore
        );
    }

    receive() external payable {}
}

