contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        require(stakeAmount > 0, "stakeAmount must be > 0");
        require(address(c) != address(0), "c unset");

        // Ensure this test contract holds enough staking tokens by staking only what it can transfer.
        // The test contract must already hold staking tokens in the fresh deployment; if not, the
        // staking call will revert and the rule is vacuously true via the revert flag below.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        bool stakeReverted;
        try c.stake(stakeAmount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        if (!stakeReverted) {
            uint256 balAfterStake = c.balanceOf(address(this));
            uint256 totalAfterStake = c.totalSupply();

            // Rule part 1: staking increases the staker balance and total supply by exactly stakeAmount.
            assert(balAfterStake == balBefore + stakeAmount);
            assert(totalAfterStake == totalBefore + stakeAmount);

            // Only attempt withdrawal of a positive amount and at most what was just staked.
            uint256 effectiveWithdraw = withdrawAmount;
            if (effectiveWithdraw == 0 || effectiveWithdraw > balAfterStake) {
                effectiveWithdraw = balAfterStake;
            }

            bool withdrawReverted;
            try c.withdraw(effectiveWithdraw, false) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }

            if (!withdrawReverted) {
                // Rule part 2: withdrawing the same effective amount restores the prior balance
                // and total supply, and reduces c's staking-token balance accordingly.
                assert(c.balanceOf(address(this)) == balAfterStake - effectiveWithdraw);
                assert(c.totalSupply() == totalAfterStake - effectiveWithdraw);

                // The staking token balance of c is only observable via its public IERC20? It is not
                // exposed directly, so we use the balanceOf/totalSupply invariants instead.
                assert(c.balanceOf(address(this)) + effectiveWithdraw == balAfterStake);
            }
        }
    }

    receive() external payable {}
}

