contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 rewardAmount1, uint256 rewardAmount2, address staker, uint256 stakeAmount) public {
        require(rewardToken != address(0), "reward token zero");
        require(staker != address(0), "staker zero");
        require(rewardAmount1 > 0, "reward amount 1 zero");
        require(stakeAmount > 0, "stake amount zero");

        // Setup: add the reward token (onlyOwner is InvMutTest because it deployed c)
        c.addReward(rewardToken);

        // Stake tokens as staker
        // staker must have approved InvMutTest? No, stakeFor uses msg.sender as from.
        // Wait, stakeFor uses stakingToken.safeTransferFrom(msg.sender, address(this), _amount) so msg.sender must be the staker.
        // We cannot call stakeFor with staker as msg.sender unless staker is this contract.
        // So we use this contract as the staker (msg.sender for the call).
        // Therefore we use address(this) as the staker.
        address thisContract = address(this);
        c.stakeFor(thisContract, stakeAmount);

        // Now notify rewards. rewardDistributor must be set to this contract (constructor does not set it, onlyOwner can).
        c.setRewardDistributor(address(this));

        // Notify first reward amount
        c.notifyRewardAmount(rewardToken, rewardAmount1);

        // Notify second reward amount (optional, but generalizes)
        if (rewardAmount2 > 0) {
            c.notifyRewardAmount(rewardToken, rewardAmount2);
        }

        // Read the claimable rewards before claiming
        uint256 claimableBefore = c.claimableRewards(thisContract, rewardToken);

        // Claim rewards
        c.getReward(thisContract, rewardToken);

        // After claiming, the claimable should be zero for the staker
        uint256 claimableAfter = c.claimableRewards(thisContract, rewardToken);

        // The total notified is rewardAmount1 + rewardAmount2 (if rewardAmount2 > 0, otherwise just rewardAmount1)
        uint256 totalNotified = rewardAmount1 + rewardAmount2;

        // General rule: The amount claimed (claimableBefore) must not exceed the total notified for the token
        // and after claiming the claimable amount must be zero.
        assert(claimableBefore <= totalNotified && claimableAfter == 0);
    }

    receive() external payable {}
}

