contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        require(stakeAmount > 0, "stake must be positive");
        require(withdrawAmount > 0, "withdraw must be positive");
        require(address(this).balance >= 0, "balance precondition");

        // stake a nonzero amount for msg.sender (this test contract)
        uint256 beforeBal = c.balanceOf(address(this));
        c.stakeFor(address(this), stakeAmount);
        uint256 afterStakeBal = c.balanceOf(address(this));

        // attempt to withdraw more than staked; must revert
        bool reverted;
        try c.withdraw(stakeAmount + withdrawAmount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);

        // now withdraw exactly the staked amount, should succeed unless it overflows
        uint256 afterBal = c.balanceOf(address(this));
        c.withdraw(stakeAmount, false);
        uint256 finalBal = c.balanceOf(address(this));

        assert(afterStakeBal == beforeBal + stakeAmount);
        assert(finalBal == afterBal - stakeAmount);
    }

    receive() external payable {}
}
